class TestScannerBaseArchitecture:
    """
    Suite to validate the architectural constraints of the ScannerPlugin ABC
    and the integrity of the Finding data model.
    """

    def test_abstract_class_instantiation(self):
        """
        Ensure that ScannerPlugin cannot be instantiated directly due to 
        abstract methods.
        """
        with pytest.raises(TypeError) as excinfo:
            ScannerPlugin({"config": "test"})
        assert "Can't instantiate abstract class ScannerPlugin" in str(excinfo.value)

    def test_finding_dataclass_initialization(self):
        """
        Validate that the Finding dataclass correctly assigns values and 
        handles the default metadata factory.
        """
        finding = Finding(
            plugin_id="TEST_ID",
            severity=Severity.CRITICAL,
            title="Critical Bug",
            description="Description",
            evidence="Evidence String",
            remediation="Fix it"
        )
        
        assert finding.plugin_id == "TEST_ID"
        assert finding.severity == Severity.CRITICAL
        assert isinstance(finding.metadata, dict)
        assert len(finding.metadata) == 0

    def test_finding_metadata_isolation(self):
        """
        Ensure that the default_factory for metadata prevents shared state 
        between Finding instances (mutable default argument trap).
        """
        f1 = Finding("ID1", Severity.INFO, "T1", "D1", "E1", "R1")
        f2 = Finding("ID2", Severity.INFO, "T2", "D2", "E2", "R2")
        
        f1.metadata["key"] = "value1"
        assert "key" not in f2.metadata

    def test_severity_enum_values(self):
        """Validate the integrity of the Severity Enum mapping."""
        assert Severity.INFO.value == 1
        assert Severity.LOW.value == 2
        assert Severity.MEDIUM.value == 3
        assert Severity.HIGH.value == 4
        assert Severity.CRITICAL.value == 5

    @pytest.mark.asyncio
    async def test_concrete_plugin_execution(self):
        """
        Validate that a concrete implementation of ScannerPlugin 
        behaves as expected.
        """
        config = {"timeout": 30, "threads": 10}
        plugin = MockScannerPlugin(config)
        
        # Test property access
        assert plugin.plugin_id == "MOCK_PLUGIN_001"
        assert plugin.config == config
        
        # Test async run method
        target = "127.0.0.1"
        findings = await plugin.run(target)
        
        assert isinstance(findings, list)
        assert len(findings) == 1
        assert isinstance(findings[0], Finding)
        assert findings[0].severity == Severity.HIGH
        assert findings[0].plugin_id == "MOCK_PLUGIN_001"

