    @pytest.mark.parametrize("evidence_type, value", [
        (str, "Port 80 open"),
        (dict, {"header": "X-Frame-Options: MISSING"}),
        (list, ["log_line_1", "log_line_2"]),
        (int, 404),
        (None, None)
    ])
    def test_finding_evidence_flexibility(self, evidence_type, value):
        """
        Verify that the 'evidence' field in Finding accepts 'Any' type 
        as per the specification.
        """
        finding = Finding(
            plugin_id="TEST",
            severity=Severity.LOW,
            title="T",
            description="D",
            evidence=value,
            remediation="R"
        )
        assert isinstance(finding.evidence, evidence_type) if evidence_type else finding.evidence is None